// Today Gen Energy
// 62: Today_Gen_PowerWh (0.1kWh)

msg.baseAddr = 62;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 62,
    quantity: 1
};
return msg;

// Generator daily operating time
// 83: Generator daily operating time (0.1h)

msg.baseAddr = 83;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 83,
    quantity: 1
};
return msg;

// Total Gen Energy
// 92+95: Total Gen PowerWh (0.1kWh, 32-bit)
// Low:92, High:95 - read 4 registers

msg.baseAddr = 92;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 92,
    quantity: 4
};
return msg;

// Gen input power
// 166: Gen input power (1W, signed)

msg.baseAddr = 166;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 166,
    quantity: 1
};
return msg;

// Gen voltage
// 181: Gen port voltage (0.1V)

msg.baseAddr = 181;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 181,
    quantity: 1
};
return msg;

// Gen frequency
// 196: Gen port frequency (0.01Hz)

msg.baseAddr = 196;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 196,
    quantity: 1
};
return msg;

// Build GeneratorDeviceState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("GeneratorDeviceState: missing base address");
    return null;
}

// Helper: signed 16-bit
function s16(v) {
    if (!Number.isFinite(v)) return 0;
    return (v & 0x8000) ? v - 0x10000 : v;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// ---- Store partials ----

// Today Energy 62
if (baseAddr === 62) {
    const todayRaw = data[0] || 0;  // 0.1kWh
    flow.set("gds_part_today", {
        todayGenEnergyKWh: Math.round(todayRaw * 0.1 * 100) / 100
    });
}

// Runtime 83
else if (baseAddr === 83) {
    const runtimeRaw = data[0] || 0;  // 0.1h
    flow.set("gds_part_runtime", {
        accumulatedRunTimeHours: Math.round(runtimeRaw * 0.1 * 10) / 10
    });
}

// Total Energy 92-95
else if (baseAddr === 92) {
    const genLow = data[0] || 0;    // 92
    const genHigh = data[3] || 0;   // 95 (index 3)
    const totalEnergy = u32(genLow, genHigh) * 0.1;
    flow.set("gds_part_total", {
        totalGenEnergyKWh: Math.round(totalEnergy * 100) / 100
    });
}

// Power 166
else if (baseAddr === 166) {
    const power = s16(data[0]);  // 1W, signed
    flow.set("gds_part_power", {
        genActivePowerW: power,
        smartLoadActivePowerW: power
    });
}

// Voltage 181
else if (baseAddr === 181) {
    const voltageRaw = data[0] || 0;  // 0.1V
    flow.set("gds_part_voltage", {
        genVoltageV: Math.round(voltageRaw * 0.1 * 10) / 10
    });
}

// Frequency 196
else if (baseAddr === 196) {
    const freqRaw = data[0] || 0;  // 0.01Hz
    flow.set("gds_part_freq", {
        genFrequencyHz: Math.round(freqRaw * 0.01 * 100) / 100
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const todayPart = flow.get("gds_part_today");
const runtimePart = flow.get("gds_part_runtime");
const totalPart = flow.get("gds_part_total");
const powerPart = flow.get("gds_part_power");
const voltagePart = flow.get("gds_part_voltage");
const freqPart = flow.get("gds_part_freq");

if (!todayPart || !runtimePart || !totalPart || !powerPart || !voltagePart || !freqPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "GeneratorDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    genVoltageV: voltagePart.genVoltageV,
    genFrequencyHz: freqPart.genFrequencyHz,
    genActivePowerW: powerPart.genActivePowerW,
    smartLoadActivePowerW: powerPart.smartLoadActivePowerW,

    todayGenEnergyKWh: todayPart.todayGenEnergyKWh,
    totalGenEnergyKWh: totalPart.totalGenEnergyKWh,
    accumulatedRunTimeHours: runtimePart.accumulatedRunTimeHours
};

// Clear partials
flow.set("gds_part_today", null);
flow.set("gds_part_runtime", null);
flow.set("gds_part_total", null);
flow.set("gds_part_power", null);
flow.set("gds_part_voltage", null);
flow.set("gds_part_freq", null);

flow.set("generatorDeviceStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Check if generator is active or if this is an RPC request
// Only send to ThingsBoard telemetry if:
// 1. Generator has power (genActivePowerW != 0)
// 2. OR Generator has voltage (genVoltageV > 0)
// 3. OR Generator has frequency (genFrequencyHz > 0)
// 4. OR This is an RPC request (always respond)

const state = msg.payload;
const isRpcRequest = msg.isRpcRequest === true;

const hasPower = state.genActivePowerW !== 0;
const hasVoltage = state.genVoltageV > 0;
const hasFrequency = state.genFrequencyHz > 0;
const isGeneratorActive = hasPower || hasVoltage || hasFrequency;

// RPC requests always get a response
if (isRpcRequest) {
    node.status({ 
        fill: "blue", 
        shape: "dot", 
        text: `RPC response - ${state.genActivePowerW}W` 
    });
    return [msg, msg];  // Send to both telemetry and RPC response
}

// Periodic poll - only send if generator is active
if (!isGeneratorActive) {
    // Check if we need to send "generator stopped" once
    const previousWasActive = flow.get("gds_previous_was_active") || false;

    if (previousWasActive) {
        // Send one "stopped" message
        flow.set("gds_previous_was_active", false);
        node.status({ fill: "grey", shape: "dot", text: "Stopped - sent" });
        return [msg, null];  // Send to telemetry only
    } else {
        // Already sent stopped, don't spam
        node.status({ fill: "grey", shape: "ring", text: "Inactive - skipped" });
        return [null, null];
    }
}

// Generator is active - send it
flow.set("gds_previous_was_active", true);

node.status({ 
    fill: "green", 
    shape: "dot", 
    text: `Active - ${state.genActivePowerW}W` 
});

return [msg, null];  // Send to telemetry only

// Only handle messages that came from RPC
if (!msg.rpcResponseTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = state;
msg.topic = msg.rpcResponseTopic;

return msg;
